test:
parent = {'Company': None, 'Engineering': 'Company', 'Search': 'Engineering', 'Platform': 'Engineering', 'Sales': 'Company', 'Infra': 'Platform'}
members = {'Alice': 'Search', 'Bob': 'Search', 'Carol': 'Platform', 'Dan': 'Sales', 'Eve': 'Engineering', 'Fran': 'Infra'}
assert closest_common_group(parent, members, ['Alice', 'Bob']) == 'Search'

parent = {'Company': None, 'Engineering': 'Company', 'Search': 'Engineering', 'Platform': 'Engineering', 'Sales': 'Company', 'Infra': 'Platform'}
members = {'Alice': 'Search', 'Bob': 'Search', 'Carol': 'Platform', 'Dan': 'Sales', 'Eve': 'Engineering', 'Fran': 'Infra'}
assert closest_common_group(parent, members, ['Alice', 'Carol']) == 'Engineering'
assert closest_common_group(parent, members, ['Alice', 'Fran']) == 'Engineering'

parent = {'Company': None, 'Engineering': 'Company', 'Search': 'Engineering', 'Platform': 'Engineering', 'Sales': 'Company', 'Infra': 'Platform'}
members = {'Alice': 'Search', 'Bob': 'Search', 'Carol': 'Platform', 'Dan': 'Sales', 'Eve': 'Engineering', 'Fran': 'Infra'}
assert closest_common_group(parent, members, ['Alice', 'Bob', 'Dan']) == 'Company'
assert closest_common_group(parent, members, ['Fran', 'Alice', 'Carol']) == 'Engineering'

parent = {'Company': None, 'Engineering': 'Company', 'Search': 'Engineering', 'Platform': 'Engineering', 'Sales': 'Company', 'Infra': 'Platform'}
members = {'Alice': 'Search', 'Bob': 'Search', 'Carol': 'Platform', 'Dan': 'Sales', 'Eve': 'Engineering', 'Fran': 'Infra'}
assert closest_common_group(parent, members, ['Eve', 'Alice']) == 'Engineering'
assert closest_common_group(parent, members, ['Carol', 'Fran']) == 'Platform'

parent = {'Root': None, 'A': 'Root', 'B': 'A'}
members = {'p': 'Root', 'q': 'B', 'r': 'A'}
query = ['q', 'p', 'r']
saved = (parent.copy(), members.copy(), query.copy())
assert closest_common_group(parent, members, query) == 'Root'
assert (parent, members, query) == saved
